mapper.insert:

  SELECT 'CR' || LPAD(SEQ_CHAT_ROOM_ID.NEXTVAL, 8, '0') FROM DUAL

	INSERT INTO BROKER_CHATROOM (
	CR_ID
	,INQUIRER_CD
	,SELLER_CD
	,LSTG_ID
	,CR_TITLE
	)VALUES (
	#{crId}
	,#{inquirerCd}
	,#{sellerCd}
	,#{lstgId}
	,#{crTitle}
	)


  SELECT 'CM' || LPAD(SEQ_CHAT_MESSAGE_ID.NEXTVAL, 8, '0') FROM DUAL

INSERT INTO CHAT_MESSAGE(
CM_ID
,CR_ID
,MBR_CD
,CM_CONT
,CM_IMG
)VALUES (
#{cmId}
,#{crId}
,#{mbrCd}
,#{cmCont}
,#{cmImg})

mapper.update:
UPDATE BROKER_CHAT_PARTICIPANT
SET BCP_STATUS = 'LEAVE'
AND BCP_LEAVED_AT = SYSDATE
WHERE CR_ID = #{crId}
and MBR_CD = #{mbrCd}

UPDATE BROKER_CHAT_PARTICIPANT
SET BCP_STATUS = 'JOIN'
AND BCP_LEAVED_AT = SYSDATE
WHERE CR_ID = #{crId}
and MBR_CD = #{mbrCd}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS EXISTS_FLAG
FROM BROKER_CHATROOM
WHERE INQUIRER_CD = #{inquirerCd} AND LSTG_ID = #{lstgId};
